<?php require __DIR__.'/config/app.php';$id=(int)($_GET['id']??0);try{$s=db()->prepare('SELECT * FROM events WHERE id=? AND is_published=1 AND event_date>=?');$s->execute([$id,date('Y-m-d')]);$event=$s->fetch();}catch(Throwable $t){$event=null;}if(!$event){http_response_code(404);$pageTitle='Event unavailable';require __DIR__.'/includes/header.php';echo '<main class="content-page"><h1>Event unavailable</h1><a href="'.url('events.php').'">Browse events</a></main>';require __DIR__.'/includes/footer.php';exit;}$u=user();$eventCategory=strtolower((string)$event['category']);$categoryRoleOptions=match($eventCategory){'sports'=>['Player / Team Participant','Team Captain','Sports Volunteer','Photography','Event Support'],'cultural'=>['Dance Performer','Music Performer','Drama / Theatre Performer','Anchor / Host','Photography','Videography','Backstage / Stage Crew','Event Volunteer'],'technical'=>['Workshop Participant','Project Presenter','Technical Volunteer','Photography','Videography','Registration & Hospitality'],'volunteer'=>['General Volunteer','Registration & Hospitality','Logistics Support','Photography','Outreach & Coordination'],default=>['Participant','Event Volunteer','Photography','Videography','Event Support']};$studentPanel=($u['role']??'')==='student';if($studentPanel)ensure_event_application_schema();$bodyClass=$studentPanel?'dashboard-page student-event-page':'';$activePage='events';$sidebarItems=[['Dashboard','student/dashboard.php'],['Explore Events','events.php'],['My Applications','student/applications.php'],['My Volunteering','student/volunteering.php'],['My Cultural Activities','student/cultural-activities.php'],['My Profile','student/profile.php'],['Notifications','notifications.php'],['Change Password','student/settings.php']];if($_SERVER['REQUEST_METHOD']==='POST'){$u=require_role('student');csrf_check();$applicantName=trim((string)($_POST['applicant_name']??''));$grNo=trim((string)($_POST['gr_no']??''));$mobile=preg_replace('/[\s-]+/','',trim((string)($_POST['mobile_number']??'')));$department=trim((string)($_POST['department']??''));$semester=(int)($_POST['semester']??0);$applicationRole=(string)($_POST['application_role']??'');$allowedRoles=$categoryRoleOptions;if($applicantName===''||mb_strlen($applicantName)>120||$grNo===''||mb_strlen($grNo)>40||!preg_match('/^(?:\+91)?[6-9][0-9]{9}$/',$mobile)||$department===''||mb_strlen($department)>100||$semester<1||$semester>12||!in_array($applicationRole,$allowedRoles,true)){flash('Please complete all application details with a valid mobile number.','error');go('event.php?id='.$id);}try{$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO event_applications(event_id,user_id,status,applied_at) VALUES(?,?,\'Pending\',NOW())');$s->execute([$id,$u['id']]);$applicationId=(int)$pdo->lastInsertId();$details=$pdo->prepare('INSERT INTO event_application_details(application_id,applicant_name,gr_no,mobile_number,department,semester,application_role) VALUES(?,?,?,?,?,?,?)');$details->execute([$applicationId,$applicantName,$grNo,$mobile,$department,$semester,$applicationRole]);$notify=$pdo->prepare("INSERT INTO notifications(user_id,title,message) SELECT u.id,'New event application',? FROM users u WHERE u.role='admin' AND u.is_active=1 AND COALESCE((SELECT in_app_notifications FROM user_settings s WHERE s.user_id=u.id),1)=1");$notify->execute([$applicantName.' applied for '.$event['title'].' as '.$applicationRole.'.']);$pdo->commit();flash('Your application was submitted for admin review.');}catch(PDOException $t){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash($t->getCode()==='23000'?'You have already applied to this event.':'Could not submit the application.','error');}catch(Throwable $t){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('Could not submit the application.','error');}go('event.php?id='.$id);}$pageTitle=$event['title'];require __DIR__.'/includes/header.php';?><?php if($studentPanel):?><div class="dash-layout"><?php require __DIR__.'/includes/sidebar.php';?><main class="content-page admin-content detail-page"><?php else:?><main class="content-page detail-page"><?php endif;?><a href="<?=url('events.php')?>">← All events</a><div class="detail-card"><img src="<?=e(image_source($event))?>" data-fallback="<?=url(image_for($event))?>" onerror="this.onerror=null;this.src=this.dataset.fallback" alt=""><div><span class="pill <?=e($event['category'])?>"><?=e(ucfirst($event['category']))?></span><h1><?=e($event['title'])?></h1><p>▦ <?=date('d M Y',strtotime($event['event_date']))?> · <?=date('g:i A',strtotime($event['event_time']??'09:00'))?></p><p>⌖ <?=e($event['venue'])?></p><p><?=nl2br(e($event['description']??''))?></p><?php if(!$u):?><a class="btn primary" href="<?=url('login.php')?>">Sign in to apply</a><?php elseif($u['role']==='student'):?><form method="post" class="event-application-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><h2>Apply to participate</h2><p class="application-category-note">Choose how you would like to take part in this <?=e(ucfirst($eventCategory))?> event.</p><label>What would you like to apply for?<select name="application_role" required><option value="">Choose a role</option><?php foreach($categoryRoleOptions as $role):?><option><?=e($role)?></option><?php endforeach;?></select></label><label>Full name<input name="applicant_name" maxlength="120" value="<?=e($u['name'])?>" required></label><label>GR No.<input name="gr_no" maxlength="40" required></label><label>Mobile Number<input type="tel" name="mobile_number" inputmode="tel" pattern="(\+91[ -]?)?[6-9][0-9]{9}" placeholder="9876543210" required></label><label>Department<input name="department" maxlength="100" required></label><label>Semester<select name="semester" required><option value="">Choose semester</option><?php for($sem=1;$sem<=12;$sem++):?><option value="<?=$sem?>">Semester <?=$sem?></option><?php endfor;?></select></label><button class="btn primary">Submit Application</button></form><?php endif;?></div></div></main><?php if($studentPanel):?></div><?php endif;?><?php require __DIR__.'/includes/footer.php';
